SELECT COUNT(*) FROM ( SELECT ROW_NUMBER() OVER(ORDER BY SYSTEM_TYPE) AS RNUM , SYSTEM_TYPE , (SELECT Z.CODE_NAME FROM CRM_CODE_DETAIL Z WHERE Z.CODE_GROUP = 'PROJECT' AND Z.P_CODE = 'PR02' AND Z.CODE = SYSTEM_TYPE) AS SYSTEM_TYPE_NM FROM CRM_AS_MGT WHERE 1=1 AND SYSTEM_TYPE NOT IN ('S012', 'S024', 'S028' ,'S029') AND PROC_STATUS NOT IN ('C000','C006','C009','C011','C013') AND DEL_YN IS NULL AND SYSTEM_TYPE IS NOT NULL
AND SYSTEM_TYPE = #{search_type7}
AND (SELECT Z.CUST_GUBUN FROM CRM_CUST_MGT Z WHERE Z.SEQ = CUST_SEQ ) = #{search_type13}
GROUP BY ROLLUP(SYSTEM_TYPE) ORDER BY RNUM )

SELECT ROW_NUMBER() OVER(ORDER BY SYSTEM_TYPE) AS RNUM , SYSTEM_TYPE , (SELECT Z.CODE_NAME FROM CRM_CODE_DETAIL Z WHERE Z.CODE_GROUP = 'PROJECT' AND Z.P_CODE = 'PR02' AND Z.CODE = SYSTEM_TYPE) AS SYSTEM_TYPE_NM
/*전년도*/ , NVL(SUM(CASE WHEN REQUEST_TYPE='C001'AND SUBSTR(AS_NO,1,4)=TO_CHAR(ADD_MONTHS(SYSDATE,-12),'YYYY')THEN 1 END),0) AS JCNT1 /*프로그램*/ , NVL(SUM(CASE WHEN (REQUEST_TYPE='C002' OR REQUEST_TYPE='C003') AND SUBSTR(AS_NO,1,4)=TO_CHAR(ADD_MONTHS(SYSDATE,-12),'YYYY') THEN 1 END),0) AS JCNT2 /*데이터*/ , NVL(SUM(CASE WHEN REQUEST_TYPE='C004' AND SUBSTR(AS_NO,1,4)=TO_CHAR(ADD_MONTHS(SYSDATE,-12),'YYYY') THEN 1 END),0) AS JCNT3 /*권한*/ , NVL(SUM(CASE WHEN REQUEST_TYPE NOT IN ('C001','C002','C003','C004') AND SUBSTR(AS_NO,1,4)=TO_CHAR(ADD_MONTHS(SYSDATE,-12),'YYYY') THEN 1 END),0) AS JCNT4 /*기타*/ , NVL(SUM(CASE WHEN SUBSTR(AS_NO,1,4)=TO_CHAR(ADD_MONTHS(SYSDATE,-12),'YYYY') THEN 1 END ),0) AS JCNT_TOT /*합계*/
/*조회기간*/ , NVL(SUM(CASE WHEN REQUEST_TYPE='C001'AND SUBSTR(AS_NO,1,8) BETWEEN REPLACE(#{search_start},'/','') AND REPLACE(#{search_end},'/','') THEN 1 END),0) AS CNT1 /*프로그램*/ , NVL(SUM(CASE WHEN (REQUEST_TYPE='C002' OR REQUEST_TYPE='C003') AND SUBSTR(AS_NO,1,8) BETWEEN REPLACE(#{search_start},'/','') AND REPLACE(#{search_end},'/','')THEN 1 END),0) AS CNT2 /*데이터*/ , NVL(SUM(CASE WHEN REQUEST_TYPE='C004' AND SUBSTR(AS_NO,1,8) BETWEEN REPLACE(#{search_start},'/','') AND REPLACE(#{search_end},'/','') THEN 1 END),0) AS CNT3 /*권한*/ , NVL(SUM(CASE WHEN REQUEST_TYPE NOT IN ('C001','C002','C003','C004') AND SUBSTR(AS_NO,1,8) BETWEEN REPLACE(#{search_start},'/','') AND REPLACE(#{search_end},'/','') THEN 1 END),0) AS CNT4 /*기타*/ , NVL(SUM(CASE WHEN SUBSTR(AS_NO,1,8) BETWEEN REPLACE(#{search_start},'/','') AND REPLACE(#{search_end},'/','') THEN 1 END ),0) AS CNT_TOT /*합계*/
/*누적*/ , NVL(SUM(CASE WHEN REQUEST_TYPE='C001'AND SUBSTR(AS_NO,1,8) BETWEEN TO_CHAR(SYSDATE,'YYYY')||'0101' AND REPLACE(#{search_end},'/','') THEN 1 END),0) AS NCNT1 /*프로그램*/ , NVL(SUM(CASE WHEN (REQUEST_TYPE='C002' OR REQUEST_TYPE='C003') AND SUBSTR(AS_NO,1,8) BETWEEN TO_CHAR(SYSDATE,'YYYY')||'0101' AND REPLACE(#{search_end},'/','') THEN 1 END),0) AS NCNT2 /*데이터*/ , NVL(SUM(CASE WHEN REQUEST_TYPE='C004' AND SUBSTR(AS_NO,1,8) BETWEEN TO_CHAR(SYSDATE,'YYYY')||'0101' AND REPLACE(#{search_end},'/','') THEN 1 END),0) AS NCNT3 /*권한*/ , NVL(SUM(CASE WHEN REQUEST_TYPE NOT IN ('C001','C002','C003','C004') AND SUBSTR(AS_NO,1,8) BETWEEN TO_CHAR(SYSDATE,'YYYY')||'0101' AND REPLACE(#{search_end},'/','') THEN 1 END),0) AS NCNT4 /*기타*/ , NVL(SUM(CASE WHEN SUBSTR(AS_NO,1,8) BETWEEN TO_CHAR(SYSDATE,'YYYY')||'0101' AND REPLACE(#{search_end},'/','') THEN 1 END ),0) AS NCNT_TOT /*합계*/
FROM CRM_AS_MGT WHERE 1=1 AND SYSTEM_TYPE NOT IN ('S012', 'S024', 'S028' ,'S029') AND PROC_STATUS NOT IN ('C000','C006','C009','C011','C013') AND DEL_YN IS NULL AND SYSTEM_TYPE IS NOT NULL
AND SYSTEM_TYPE = #{search_type7}
AND (SELECT Z.CUST_GUBUN FROM CRM_CUST_MGT Z WHERE Z.SEQ = CUST_SEQ ) = #{search_type13}
GROUP BY ROLLUP(SYSTEM_TYPE) ORDER BY RNUM

/* A/S관리 AS상세정보등록 조회시 */
SELECT AS_NO ,CN_AS_NO ,ACCEPT_DT ,ACCEPT_TIME ,ACCEPT_ROUTE ,CUST_CODE ,APPLY_NM ,APPLY_ID ,APPLY_TEL ,SYSTEM_TYPE ,INQUIRY_DT ,INQUIRY_TYPE ,CALL_CONTENT ,FILE_SEQ ,PROC_DT ,PROC_TIME ,INPORTANCE ,CAUSE_TYPE ,ACTION_TYPE ,ASSIGN_ID ,PROC_STATUS ,ACTION_CONTENT ,PROC_GRADE ,PROC_GRADE ,PROC_BUILD_INFO ,PROC_FILE_INFO ,PROC_DB_INFO ,PROC_TEST_INFO ,MEMO ,REG_DATE ,REG_ID ,UPT_DATE ,UPT_ID ,STAR_STATE ,STAR_CONTENT ,REQUEST_CONTENT ,ATTACH_SEQ2 ,(SELECT EMP_NM FROM CRM_EMP_MGT WHERE ASSIGN_ID = EMP_NO ) ASSIGN_NM ,CUST_SEQ ,SEND_EMAIL ,SEND_SMS ,APPLY_EMAIL ,APPLY_SMS_TEL ,OPER_SEQ ,APPROVAL_DT ,APPROVAL_TIME ,APPROVAL_ID ,APPROVAL_NM ,(SELECT CASE WHEN (SELECT COUNT(*) FROM CRM_AS_MGT WHERE CN_AS_NO = #{as_no, jdbcType=VARCHAR}) = 0 THEN 'N' ELSE CASE WHEN (SELECT COUNT(*) FROM CRM_AS_MGT WHERE CN_AS_NO = #{as_no, jdbcType=VARCHAR}) = (SELECT COUNT(*) FROM CRM_AS_MGT WHERE CN_AS_NO = #{as_no, jdbcType=VARCHAR} AND PROC_STATUS IN ('C009', 'C011', 'C013')) THEN 'N' ELSE 'Y' END END AS WORK_TIME_YN FROM DUAL) WORK_TIME_YN ,(SELECT CASE WHEN (SELECT COUNT(*) FROM CRM_AS_MGT WHERE CN_AS_NO = #{as_no, jdbcType=VARCHAR}) = 0 THEN (SELECT WORK_TIME FROM CRM_AS_MGT WHERE AS_NO = #{as_no, jdbcType=VARCHAR}) ELSE CASE WHEN (SELECT COUNT(*) FROM CRM_AS_MGT WHERE CN_AS_NO = #{as_no, jdbcType=VARCHAR}) = (SELECT COUNT(*) FROM CRM_AS_MGT WHERE CN_AS_NO = #{as_no, jdbcType=VARCHAR} AND PROC_STATUS IN ('C009','C011','C013')) THEN (SELECT WORK_TIME FROM CRM_AS_MGT WHERE AS_NO = #{as_no, jdbcType=VARCHAR}) ELSE (SELECT SUM(WORK_TIME) FROM CRM_AS_MGT WHERE CN_AS_NO = #{as_no, jdbcType=VARCHAR} AND PROC_STATUS IN ('C005','C012')) END END AS WORK_TIME FROM DUAL) WORK_TIME ,(SELECT Z.CODE_NAME FROM CRM_CODE_DETAIL Z WHERE Z.CODE_GROUP = 'AS' AND Z.P_CODE = 'CD04' AND Z.CODE = INPORTANCE) INPORTANCE_NM ,COMPLETE_DT ,REQUEST_TYPE ,SHARED_DOC_ID ,SHARED_DOC_IDX ,SHARED_ATTACH ,SHARED_FILENM ,SHARED_FILEPATH ,PROC_GUBUN ,(SELECT Z.CODE_NAME FROM CRM_CODE_DETAIL Z WHERE Z.CODE_GROUP = 'AS' AND Z.P_CODE = 'CD08' AND Z.CODE = PROC_GUBUN) PROC_GUBUN_NM ,PROC_PROCESS_SP ,PROC_FUNCTION_SP ,PROC_SCREEN_SP ,PROC_TABLE_SP ,PROC_INTERFACE_SP ,PROC_ERD_SP ,(SELECT Z.CODE_NAME FROM CRM_CODE_DETAIL Z WHERE Z.CODE_GROUP = 'AS' AND Z.P_CODE = 'CD07' AND Z.CODE = PROC_GRADE) PROC_GRADE_NM
/* 추가 2020.08.03. - 보완필요 */ ,(SELECT Z.CUST_GUBUN FROM CRM_CUST_MGT Z WHERE Z.ERP_CODE = CUST_CODE) CUST_GUBUN /*거래처구분(CUST-CD01) C001 JW그룹*/ ,(SELECT Z.CODE_NAME FROM CRM_CODE_DETAIL Z WHERE Z.CODE_GROUP = 'AS' AND Z.P_CODE = 'CD03' AND Z.CODE = REQUEST_TYPE) REQUEST_TYPE_NM /*문의유형 명칭*/ ,(SELECT Z.VAL1 FROM CRM_CODE_DETAIL Z WHERE Z.CODE_GROUP = 'AS' AND Z.P_CODE = 'CD03' AND Z.CODE = REQUEST_TYPE) GYUL_GB1 /*승인대상(팀장)*/ ,(SELECT Z.VAL2 FROM CRM_CODE_DETAIL Z WHERE Z.CODE_GROUP = 'AS' AND Z.P_CODE = 'CD03' AND Z.CODE = REQUEST_TYPE) GYUL_GB2 /*승인대상(배포)*/ ,(SELECT Z.VAL1 FROM CRM_CODE_DETAIL Z WHERE Z.CODE_GROUP = 'AS' AND Z.P_CODE = 'CD09' AND SUBSTR(Z.CODE_NAME,1,5) = (SELECT z.dept2_cd FROM crm_emp_mgt z WHERE z.emp_no = ASSIGN_ID)) GYUL_EMP1 /*승인자(팀장)*/ ,(SELECT Z.VAL2 FROM CRM_CODE_DETAIL Z WHERE Z.CODE_GROUP = 'AS' AND Z.P_CODE = 'CD09' AND SUBSTR(Z.CODE_NAME,1,5) = (SELECT z.dept2_cd FROM crm_emp_mgt z WHERE z.emp_no = ASSIGN_ID)) GYUL_EMP2 /*승인자(배포)*/ ,APPR_YN1 ,APPR_EMP1 ,(SELECT EMP_NM FROM CRM_EMP_MGT WHERE EMP_NO = APPR_EMP1 ) APPR_EMP1_NM /*팀장승인자 이름*/ ,APPR_DATE1 ,(SELECT Z.VAL3 FROM CRM_CODE_DETAIL Z WHERE Z.CODE_GROUP = 'AS' AND Z.P_CODE = 'CD09' AND SUBSTR(Z.CODE_NAME, 1, 5) = (SELECT z.dept2_cd FROM CRM_EMP_MGT z WHERE z.emp_no = ASSIGN_ID)) AS APPR_SUB_EMP1 /*팀장승인 대체자(2차 결재자)*/ ,(SELECT Z.VAL5 FROM CRM_CODE_DETAIL Z WHERE Z.CODE_GROUP = 'AS' AND Z.P_CODE = 'CD09' AND SUBSTR(Z.CODE_NAME, 1, 5) = (SELECT z.dept2_cd FROM CRM_EMP_MGT z WHERE z.emp_no = ASSIGN_ID)) AS APPR_SSUB_EMP1 /*팀장승인 대체자(3차 결재자)*/ ,APPR_YN2 ,APPR_EMP2 ,(SELECT EMP_NM FROM CRM_EMP_MGT WHERE EMP_NO = APPR_EMP2 ) APPR_EMP2_NM /*배포승인자 이름*/ ,APPR_DATE2 ,(SELECT Z.VAL4 FROM CRM_CODE_DETAIL Z WHERE Z.CODE_GROUP = 'AS' AND Z.P_CODE = 'CD09' AND SUBSTR(Z.CODE_NAME, 1, 5) = (SELECT z.dept2_cd FROM CRM_EMP_MGT z WHERE z.emp_no = ASSIGN_ID)) AS APPR_SUB_EMP2 /*배포승인 대체자(2차 결재자)*/ ,(SELECT Z.VAL6 FROM CRM_CODE_DETAIL Z WHERE Z.CODE_GROUP = 'AS' AND Z.P_CODE = 'CD09' AND SUBSTR(Z.CODE_NAME, 1, 5) = (SELECT z.dept2_cd FROM CRM_EMP_MGT z WHERE z.emp_no = ASSIGN_ID)) AS APPR_SSUB_EMP2 /*배포승인 대체자(3차 결재자)*/ ,DISTR_FILEPATH ,DISTR_SVN_VER ,DISTR_DT ,DISTR_DT ,CMC_PIC /*CMC담당자 (AS-CD10)*/ ,PROGRAM_SATISFACTION /*프로그램 만족도 (AS-CD11)*/ ,MODULE_NAME /*모듈(AS-SD12)*/ ,(SELECT Z.CODE_NAME FROM CRM_CODE_DETAIL Z WHERE Z.CODE_GROUP = 'AS' AND Z.P_CODE = 'CD13' AND Z.CODE = CATEGORY_ID) CATEGORY_NAME ,CATEGORY_ID /*중분류*/ ,PROGRAM_ID /*프로그램ID*/ ,(SELECT Z.PROGRAM_NM FROM CRM_AS_PROGRAM_MGT Z WHERE Z.PROGRAM_CODE = PROGRAM_ID) AS PROGRAM_NAME /*프로그램*/ ,PEER_REVIEW_NM /*동료검토자 추가 2021.07.05*/ ,USER_TEST_YN /*현업테스트여부 추가 2021.07.05*/ ,NORMAL_OPER_YN /*정상작동여부 추가 2021.07.05*/ ,TEST_NOTE /*테스트 비고 추가 2021.07.05*/ ,USER_TEST_DT /*현업테스트일자 추가 2021.07.29*/ ,USER_TEST_TIME /*현업테스트시간 추가 2022.01.24*/ ,SHARED_TAG /*jw그룹웨어 승인자 접수의견 추가 2021.09.08*/ ,USER_TEST_ID /*현업테스트자ID 추가 2021.11.29*/ ,(SELECT EMP_NAME FROM CRM_CUST_EMP WHERE EMP_ID = USER_TEST_ID) AS USER_TEST_NM /*현업테스트자이름 추가 2021.11.29*/ ,USER_TEST_IP /*현업테스트자IP주소 추가 2021.11.29*/ ,TARGET_PROJECT ,EXPECTED_WORK_TIME ,PROGRESS_RATE FROM CRM_AS_MGT WHERE AS_NO = #{as_no, jdbcType=VARCHAR}


