SELECT OUT_TB.* , (SELECT CODE_NAME FROM CRM_CODE_DETAIL Z WHERE CODE_GROUP='AS' AND P_CODE ='CD01' AND CODE = OUT_TB.PROC_STATUS) PROC_STATUS_NM , (SELECT COUNT(*) FROM CRM_AS_MGT Z WHERE Z.CN_AS_NO = OUT_TB.AS_NO AND Z.PROC_STATUS IN ('C003' , 'C004' , 'C005') ) CN_COUNT FROM ( SELECT IN_TB.*
, ROW_NUMBER() OVER (ORDER BY IN_TB.AS_NO ) AS RNUM , ROW_NUMBER() OVER (ORDER BY IN_TB.ACCEPT_DT ) AS RNUM , ROW_NUMBER() OVER (ORDER BY IN_TB.ACCEPT_DT DESC ) AS RNUM
FROM ( SELECT A.ACCEPT_DT , A.AS_NO , A.CN_AS_NO , A.PROC_STATUS , A.CUST_CODE FROM CRM_AS_MGT A WHERE A.DEL_YN IS NULL AND CUST_CODE = #{cust_code, jdbcType=VARCHAR}
AND PROC_STATUS = #{search_type2, jdbcType=VARCHAR}
) IN_TB ) OUT_TB ORDER BY RNUM DESC


select count(assign_id) as cnt from crm_as_mgt
where (del_yn is null or del_yn = 'N')
and assign_id = #{id}

UPDATE CRM_AS_MGT 
SET
 PROC_STATUS =#{proc_status}
,APPROVAL_DT =#{approval_dt}
,APPROVAL_TIME =#{approval_time}
,APPROVAL_ID =#{approval_id}
WHERE 
	AS_NO =#{as_no}

SELECT in_tb.*, (SELECT z.code_name FROM crm_code_detail z WHERE z.code_group = 'AS' AND z.p_code = 'CD01' AND z.code = in_tb.proc_status ) AS proc_status_nm, /* 처리상태 명칭 */ ( SELECT z.code_name FROM crm_code_detail z WHERE z.code_group = 'AS' AND z.p_code = 'CD04' AND z.code = in_tb.inportance ) AS inportance_nm, /* 중요도 명칭 */ ( SELECT z.code_name FROM crm_code_detail z WHERE z.code_group = 'PROJECT' AND z.p_code = 'PR02' AND z.code = in_tb.system_type ) AS SYSTEM_TYPE_NM, ( SELECT z.code_name FROM crm_code_detail z WHERE z.code_group = 'OPERATE' AND z.p_code = system_type AND z.code = in_tb.inquiry_type) AS inquiry_TYPE_NM, TO_CHAR(TO_DATE(in_tb.accept_dt,'yyyyMMdd'),'yyyy-MM-dd') accept_dt, TO_CHAR(TO_DATE(in_tb.inquiry_dt,'yyyyMMdd'),'yyyy-MM-dd') inquiry_dt, 1 FROM ( SELECT a.as_no, a.cn_as_no, a.apply_nm, a.proc_status, /* 처리상태 C */ a.cust_code, /* 거래처 코드 (cust_code) */ b.cust_kor_name, /* 거래처명 */ a.accept_route, /* 접수경로 C */ a.inportance, /* 중요도 C */ a.cause_type, /* 원인유형 C */ a.action_type, /* 조치유형 C */ a.assign_id, /* 처리담당자 아이디 */ a.call_content, /* 요청내용 */ a.OPER_SEQ, b.erp_code, nvl(( SELECT z.emp_nm FROM crm_emp_mgt z WHERE z.emp_no = a.assign_id ),'-') emp_nm, /* 처리담당자 이름 */ A.system_type, A.inquiry_type, C.system_nm, A.accept_dt, A.inquiry_dt FROM crm_as_mgt a , crm_cust_mgt b, crm_operate_mgt c WHERE 1=1 AND a.cust_code = b.erp_code AND A.OPER_SEQ = C.OPER_SEQ AND (A.DEL_YN IS NULL OR A.DEL_YN = 'N') AND as_no in (${asno})
AND B.CUST_GUBUN = #{cust_gubun}
) in_tb WHERE 1=1 ORDER BY IN_TB.AS_NO DESC

/*[egov-as-query.xml] asDAO.getAsEmailInfo*/ SELECT A.AS_NO, ( SELECT Z.CODE_NAME FROM CRM_CODE_DETAIL Z WHERE Z.CODE_GROUP = 'PROJECT' AND Z.P_CODE = 'PR02' AND Z.CODE = A.SYSTEM_TYPE ) AS SYSTEM_TYPE_NM, /*시스템유형*/ ( SELECT Z.CODE_NAME FROM CRM_CODE_DETAIL Z WHERE Z.CODE_GROUP = 'OPERATE' AND Z.P_CODE = A.SYSTEM_TYPE AND Z.CODE = A.INQUIRY_TYPE) AS INQUIRY_TYPE_NM, /*업무유형*/ TO_CHAR(TO_DATE(A.ACCEPT_DT,'YYYYMMDD'),'YYYY-MM-DD') ACCEPT_DT, /*접수시간*/ TO_CHAR(TO_DATE(A.ACCEPT_TIME,'HH24MISS'),'HH24:MI:SS') ACCEPT_TIME, /*접수시간*/ A.CALL_CONTENT, (SELECT DISTINCT(CUST_KOR_NAME) FROM CRM_CUST_MGT M WHERE 1=1 AND A.CUST_CODE=M.ERP_CODE)CUST_KOR_NAME, /*거래처명*/ A.CUST_CODE, (SELECT CUST_GUBUN FROM CRM_CUST_MGT WHERE ERP_CODE = A.CUST_CODE ) AS CUST_GUBUN, /*2022.01.이설아 추가*/ A.APPLY_ID, A.APPLY_NM, A.APPLY_EMAIL, /* 요청자 메일수신주소 */ A.SEND_EMAIL, /* 이메일 발송여부(Y/N) */ A.APPLY_TEL, A.ASSIGN_ID, E.EMP_NM, E.DEPT1_NM, E.DEPT2_NM, E.DEPT_GRADE_NM, E.E_MAIL AS SENDER_EMAIL, E.COMPANY_NO, A.ACTION_CONTENT, A.ATTACH_SEQ2, /* 첨부파일 멀티파일SEQ(조치) */ A.ACTION_TYPE, /*2023.11.06 조치유형관련*/ (SELECT Z.CODE_NAME FROM CRM_CODE_DETAIL Z WHERE Z.CODE_GROUP = 'AS' AND Z.P_CODE = 'CD05' AND Z.CODE = A.CAUSE_TYPE) CAUSE_TYPE_NM, (SELECT Z.CODE_NAME FROM CRM_CODE_DETAIL Z WHERE Z.CODE_GROUP = 'AS' AND Z.P_CODE = 'CD06' AND Z.CODE = A.ACTION_TYPE) ACTION_TYPE_NM, (SELECT Z.CODE_NAME FROM CRM_CODE_DETAIL Z WHERE Z.CODE_GROUP = 'AS' AND Z.P_CODE = 'CD03' AND Z.CODE = A.REQUEST_TYPE) REQUEST_TYPE_NM, A.REQUEST_TYPE, C.SYSTEM_NM, A.PROC_STATUS, (SELECT Z.CODE_NAME FROM CRM_CODE_DETAIL Z WHERE Z.CODE_GROUP = 'AS' AND Z.P_CODE = 'CD01' AND Z.CODE = A.PROC_STATUS) PROC_STATUS_NM, /*처리상태*/ TO_CHAR(TO_DATE(A.INQUIRY_DT,'YYYYMMDD'),'YYYY-MM-DD') INQUIRY_DT, /*처리요청일자*/ TO_CHAR(TO_DATE(A.PROC_DT,'YYYYMMDD'),'YYYY-MM-DD') PROC_DT, /*처리예정일자*/ TO_CHAR(TO_DATE(A.COMPLETE_DT,'YYYYMMDD'),'YYYY-MM-DD') COMPLETE_DT, /*처리일자*/
CASE WHEN a.proc_status IN ('C005','C012','C013') THEN '2' ELSE '1' END AS APPR_GB, /*승인구분 1 접수(팀장), 2 배포*/ A.APPR_EMP1, /*팀장승인 승인자*/ A.APPR_EMP2, /*배포승인 승인자*/ A.SHARED_DOC_IDX
FROM CRM_AS_MGT A, CRM_EMP_MGT E, CRM_OPERATE_MGT C WHERE 1=1 AND AS_NO = #{as_no} AND A.ASSIGN_ID = E.EMP_NO(+) AND A.OPER_SEQ = C.OPER_SEQ

mapper.update:
UPDATE TBL_DOCINFO 
   SET LU_FLAG = 'Y'
 WHERE IDX = #{idx}

	UPDATE TBL_WORKER_INFO
	   SET WORK_NM 	= #{emp_nm}
		 , WORK_TEL = #{company_no}
    	 , WORK_MAIL= #{sender_email}
     WHERE IDX =	#{shared_doc_idx}

mapper.select:
SELECT NVL(SHARED_DOC_IDX,0) 
FROM CRM_AS_MGT
WHERE AS_NO = #{as_no}

SELECT COUNT(*) FROM ( SELECT A.CODE FROM CRM_CODE_DETAIL A WHERE A.CODE_GROUP = 'AS' AND A.P_CODE = 'CD13' AND USE_YN = 'Y'
AND A.VAL1 = #{search_text2}
AND (UPPER(A.CODE_NAME) LIKE '%'|| UPPER(#{search_text}) ||'%' OR A.CODE LIKE '%' || #{search_text}||'%')
)

SELECT IN_TB.* FROM( SELECT A.CODE_NAME AS CATEGORY_NAME , A.CODE AS CATEGORY_ID ,ROW_NUMBER() OVER (ORDER BY A.P_CODE ) AS RNUM FROM CRM_CODE_DETAIL A WHERE A.CODE_GROUP = 'AS' AND A.P_CODE = 'CD13' AND USE_YN = 'Y'
AND A.VAL1 = #{search_text2}
AND (UPPER(A.CODE_NAME) LIKE '%'|| UPPER(#{search_text}) ||'%' OR A.CODE LIKE '%' || #{search_text}||'%')
) IN_TB WHERE RNUM BETWEEN #{startRow, jdbcType=INTEGER} AND #{endRow, jdbcType=INTEGER} ORDER BY RNUM DESC

	    SELECT COUNT(*)
	    FROM (
	    	SELECT A.PROGRAM_NM
            FROM CRM_AS_PROGRAM_MGT A 
            WHERE 1 = 1

				AND A.CATEGORIES = #{search_text3}


				AND A.SYSTEM = #{search_text4}


				AND (UPPER(A.PROGRAM_NM) LIKE '%'|| UPPER(#{search_text}) ||'%'  OR A.PROGRAM_CODE LIKE '%' || #{search_text}||'%')

	    )


	   SELECT IN_TB.*  FROM(
	    	SELECT A.PROGRAM_NM AS PROGRAM_NAME
	    	, A.PROGRAM_CODE AS PROGRAM_ID
	    	, A.CATEGORIES AS CATEGORY_ID
	    	,(SELECT Z.CODE_NAME FROM CRM_CODE_DETAIL Z WHERE Z.CODE_GROUP = 'AS' AND Z.P_CODE = 'CD13' AND Z.CODE = A.CATEGORIES) CATEGORY_NAME
            ,ROW_NUMBER() OVER (ORDER BY A.PROGRAM_CODE ) AS RNUM 
            FROM CRM_AS_PROGRAM_MGT A 
            WHERE 1 = 1

				AND A.CATEGORIES = #{search_text3}


				AND A.SYSTEM = #{search_text4}


				AND (UPPER(A.PROGRAM_NM) LIKE '%'|| UPPER(#{search_text}) ||'%'  OR A.PROGRAM_CODE LIKE '%' || #{search_text}||'%')

		) IN_TB
		WHERE RNUM BETWEEN #{startRow, jdbcType=INTEGER} AND #{endRow, jdbcType=INTEGER}

mapper.update:
/*[egov-as-query.xml] asDAO.updateUserTest*/
	UPDATE CRM_AS_MGT 
	   SET USER_TEST_YN		= #{user_test_yn, jdbcType=VARCHAR}
		 , USER_TEST_DT 	= TO_CHAR(SYSDATE,'YYYYMMDD')
		 , USER_TEST_TIME 	= TO_CHAR(SYSDATE,'HH24:MI:SS')
		 , USER_TEST_IP 	= #{user_test_ip, jdbcType=VARCHAR}
		 , USER_TEST_ID 	= #{user_test_id, jdbcType=VARCHAR}
		 , NORMAL_OPER_YN 	= #{normal_oper_yn, jdbcType=VARCHAR}
		 , TEST_NOTE 		= #{test_note, jdbcType=VARCHAR}
	WHERE AS_NO 			= #{as_no, jdbcType=VARCHAR}
